{
  "items": [
    {
      "title": "Roper Center for Public Opinion Research – Uruguay, 1960s Public Opinion Surveys",
      "url_or_doi": "https://ropercenter.cornell.edu/featured-collections/uruguay",
      "justification": "One of the most directly relevant sources for studying social behaviour and attitudes in Uruguay during the 1960s. The Roper Center identifies 19 survey datasets from Uruguay for this decade. Topics include political preferences, voting behaviour, government evaluations, economic conditions, social protests, strikes, and international relations. Surveys were conducted by organizations including Gallup Uruguay. Some datasets may require institutional access."
    },
    {
      "title": "Latin American USIA Reports – Uruguay Public Opinion Surveys, 1960–1964",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "An important historical collection of public opinion research conducted by the United States Information Agency (USIA). It includes surveys involving Uruguay between 1960 and 1964, examining attitudes toward the United States, communism, Fidel Castro, economic development, and international politics. Particularly useful for investigating political attitudes, ideological orientations, and public perceptions during the Cold War. The collection includes historical survey reports; availability of underlying respondent-level data should be verified."
    },
    {
      "title": "Montevidean Attitudes toward the US Before and After President Eisenhower's Visit (1960)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A historical public opinion study focusing specifically on Montevideo in 1960. Listed as USIA Report R256, it examines attitudes toward the United States surrounding President Dwight Eisenhower's visit. Relevant for studying public opinion, international perceptions, political attitudes, and changes in collective sentiment in urban Uruguay. The linked collection provides the report listing rather than a confirmed downloadable microdata file."
    },
    {
      "title": "Encuesta sobre la Visita al Uruguay del Presidente Eisenhower (1960)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A public opinion survey conducted on March 2–3, 1960, before President Eisenhower's visit to Uruguay. Catalogued as USIA Report R142, it provides historical evidence of Uruguayan attitudes toward American leadership and international relations. Particularly relevant for examining political opinions and public sentiment at the beginning of the 1960s. Access to original individual-level survey responses is not confirmed."
    },
    {
      "title": "The Impact of Castro upon Latin American Public Opinion (1961)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative public opinion research report from February 1961 covering seven Latin American countries, including Uruguay. Catalogued as USIA Report R258, it examines public responses to Fidel Castro and political developments in Cuba. Useful for studying ideological attitudes, political identification, international perceptions, and social reactions to revolutionary movements during the early 1960s."
    },
    {
      "title": "The Climate of Opinion in Latin America for the Alliance for Progress (1961)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative survey report published in August 1961, covering Uruguay and six other Latin American countries. Listed as USIA Report R261, it investigates public attitudes toward the Alliance for Progress and related political and economic developments. Relevant for researching perceptions of modernization, economic assistance, political institutions, and social development in Uruguay."
    },
    {
      "title": "The General Pattern of Exposure to Mass Media in Seven Latin American Countries (1961)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A particularly relevant historical survey report for studying social behaviour rather than exclusively political opinions. Published in November 1961 as USIA Report R564, it includes Uruguay alongside Brazil, Mexico, Argentina, Peru, Colombia, and Venezuela. The study examines patterns of exposure to mass media, providing evidence about communication habits, information consumption, and media engagement among Latin American populations during the early 1960s."
    },
    {
      "title": "The Economic and Political Climate of Opinion in Latin America and Attitudes toward the Alliance for Progress (1963)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative public opinion study published on June 25, 1963, including Uruguay among seven Latin American countries. Identified as USIA Report R218, it addresses economic and political perceptions and attitudes toward the Alliance for Progress. Useful for analyzing social expectations, economic satisfaction, political orientations, and attitudes toward development initiatives during the 1960s."
    },
    {
      "title": "Roper Center – Latin American Data Bank",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-data-bank",
      "justification": "A historical survey archive containing public opinion research conducted throughout Latin America, including Uruguay. The collection brings together surveys produced by universities, research institutes, individual scholars, and polling organizations. It provides a useful starting point for identifying additional 1960s Uruguayan surveys concerning political participation, economic attitudes, government evaluations, and collective behaviour. Dataset availability and access conditions vary."
    },
    {
      "title": "Uruguay General Population Census IV and Housing Census II – IPUMS Subset (1963)",
      "url_or_doi": "https://microdata.worldbank.org/catalog/1079",
      "justification": "A major quantitative source for investigating Uruguayan society in 1963. The dataset contains individual- and household-level census microdata, enabling research into demographic characteristics, household structures, educational attainment, occupations, migration, and social stratification. Although it does not directly measure subjective attitudes or opinions, it provides essential evidence about social behaviour, living arrangements, and socioeconomic conditions in Uruguay during the 1960s."
    },
    {
      "title": "Uruguay – General Population Census IV and Housing II, 1963 (International Household Survey Network)",
      "url_or_doi": "https://catalog.ihsn.org/catalog/2639/get-microdata",
      "justification": "An alternative official catalogue entry for Uruguay's 1963 population and housing census microdata. Produced by the General Office of Statistics and Censuses and distributed through IPUMS, this resource provides documentation and access information for historical demographic and socioeconomic data. Relevant for examining household composition, education, employment, population characteristics, and patterns of social organization during the 1960s. It describes the same underlying census as the World Bank entry."
    },
    {
      "title": "IPUMS International Research Data Enclave – Uruguay 1963 Full-Count Census",
      "url_or_doi": "https://international.ipums.org/international/irde_data_list.shtml",
      "justification": "Provides information about the availability of Uruguay's complete 1963 census through the IPUMS International Research Data Enclave. The full-count microdata include detailed demographic, occupational, and geographic information. Particularly valuable for examining socioeconomic inequalities, residential patterns, internal migration, occupational structures, and household characteristics in 1960s Uruguay. This is a restricted-access research resource rather than an unrestricted public download."
    },
    {
      "title": "IPUMS Latin America Project – Uruguay 1963 Census Documentation",
      "url_or_doi": "https://users.pop.umn.edu/~rmccaa/ipumsla/docsdata.htm",
      "justification": "A historical documentation resource for Latin American census microdata, including Uruguay's 1963 census. It identifies recovered census materials such as enumeration forms, coding documentation, frequency tables, and supporting records. Useful for researchers reconstructing demographic and socioeconomic characteristics of Uruguay during the 1960s or interpreting historical census variables. This resource primarily provides documentation rather than public opinion survey data."
    },
    {
      "title": "Opinión Pública en Uruguay – Universidad de la República",
      "url_or_doi": "https://umad-fcs.github.io/Piso-I-OP/",
      "justification": "An academic resource developed by the Unidad de Métodos y Acceso a Datos at Uruguay's Universidad de la República. It documents the development of public opinion research in Uruguay, noting that opinion surveys were already being conducted around 1956 and became prominent in newspapers during the late 1950s and 1960s. Particularly useful for identifying historical polling organizations, locating references to early surveys, and understanding the development of opinion research in Uruguay. It is a contextual research resource, not a confirmed repository of downloadable 1960s microdata."
    }
  ]
}
